content.content:
1	/**
2	 * Record the two build lanes of the `angular-tiny-translator-v0-12-0`
3	 * migration cell — the Angular 4–6 band cell, and the adapter's first lift of
4	 * the pre-`angular.json` Angular CLI workspace format.
5	 *
6	 * Lane one is the era baseline: the pinned tree on its own cell — Node 8.9.3
7	 * under Rosetta 2, yarn 1.3.2, the era closure restored from the ingest cache —
8	 * built twice with the plain `ng build --prod --aot` variant to see whether the
9	 * restored cache still emits the same bytes. The ingest recorded *two*
10	 * materially different production artifacts for this application, and this lane
11	 * uses the plain one; which one it is and why is stated in the record.
12	 *
13	 * Lane two is the migrated tree: the adapter's composed changeset applied to the
14	 * same pinned tree. The changeset begins with something no earlier cell needed —
15	 * an `angular.json` synthesized from `.angular-cli.json`, because every other
16	 * capability in `@versionless/angular` expects the modern workspace format and
17	 * the era document has neither a `projects` map nor an `architect` target.
18	 *
19	 * This driver is fixture-scoped: it knows where this fixture's lanes were
20	 * materialised. Every decision about *what to change* lives in
21	 * `@versionless/angular`, which knows nothing about this application.
22	 */
23	
24	import { readdir, readFile, mkdir, writeFile } from 'node:fs/promises';
25	import * as path from 'pathe';
26	import {
27		migrateAngularCliEraWorkspace,
28		ANGULAR_16_BROWSER_CELL,
29		type AngularMigration,
30		type WorkspaceFile,
31	} from '../../../frameworks/angular/src/index.ts';
32	import { canonical, sha256 } from './angular-factoriolab-migration-run.ts';
33	import {
34		inventoryOf,
35		isByteStable,
36		sealRecord,
37		verifySealedRecord,
38		type DistEntry,
39		type SealedRecord,
40	} from './angular-factoriolab-build-lanes-run.ts';
41	
42	const repositoryRoot = path.resolve(import.meta.dirname, '../../../..');
43	const evidenceDirectory = path.join(
44		repositoryRoot,
45		'evidence/runs/angular-tiny-translator-v0-12-0',
46	);
47	
48	export const UNIT = 'lrapr-t006/u17-tiny-translator-migration-lanes';
49	export const CONSENT = 'VL-LEGACY-CORPUS-2026-08-10';
50	
51	export const SOURCE_TREE = path.join(
52		repositoryRoot,
53		'.versionless/cache/angular-tiny-translator-v0-12-0-source/verify/extracted',
54		'tiny-translator-08dcacf6a41d5a6f6dfbc71d858adcdc4c85691a',
55	);
56	export const BASELINE_DIRECTORY = path.join(
57		repositoryRoot,
58		'.versionless/cache/angular-tiny-translator-v0-12-0-baseline',
59	);
60	export const MIGRATED_STAGE = path.join(
61		repositoryRoot,
62		'.versionless/stage/angular-tiny-translator-v0-12-0-u17',
63	);
64	
65	export const ERA_LANE_FILE = 'u17-era-baseline.json';
66	export const MIGRATED_LANE_FILE = 'u17-migrated-lane.json';
67	export const CHANGESET_FILE = 'u17-composed-changeset.json';
68	
69	/**
70	 * Which of the two production artifacts the ingest recorded this lane builds,
71	 * restated here rather than left in the ingest for a reader to go and find.
72	 */
73	export const ERA_VARIANT =
74		'The plain `ng build --prod --aot` variant. This application has two materially different production artifacts: the plain one, and the one the repository\'s own `build-prod-<lang>` chain produces by rewriting the literal %BASE_HREF% in src/environments/environment.prod.ts, compiling one locale from a committed XLIFF, and copying an ngsw-worker.js beside a generated ngsw.json. The plain variant registers a service worker at the un-substituted literal \'%BASE_HREF%ngsw-worker.js\' and ships no worker for it to find. This lane\'s parity story is the plain variant, because it is the one the migrated lane could ever be compared against: the locale chain is a repository script, not a build the adapter migrates.';
75	
76	export const ERA_NOT_ESTABLISHED: readonly string[] = Object.freeze([
77		'Byte stability across two consecutive builds on one host is repeatability, not reproducibility: nothing here establishes that another host, another day or another clock would emit the same bytes.',
78		'No browser opened these bundles. Nothing about their behaviour is observed.',
79		'The plain variant\'s service-worker registration points at an un-substituted literal and no worker ships beside it. That is recorded as found; it is not repaired and not masked.',
